def write_batch(batch, label):
    for cid, body in batch:
        rec = {"case_id": cid, "prediction_text": body["prediction_text"],
               "basis": body["basis"], "confidence": body["confidence"],
               "trigger": body["trigger"]}
        p = os.path.join(OUT, cid + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    # assert per batch: re-read each file exactly by id
    for cid, _ in batch:
        p = os.path.join(OUT, cid + ".json")
        d = json.load(open(p, encoding="utf-8"))
        assert d["case_id"] == cid, cid
        assert set(["case_id","prediction_text","basis","confidence","trigger"]) <= set(d.keys()), cid
        assert 0.0 <= d["confidence"] <= 1.0, cid
        tr = d["trigger"]
        assert all(isinstance(tr[k], bool) for k in ("changed_main","reserve_used","disputed")), cid
        assert isinstance(tr["reason"], str), cid
        assert d["prediction_text"].strip() and d["basis"].strip(), cid
    print(label, "OK", len(batch))

write_batch(B21, "B21")
write_batch(B22, "B22")

# trigger tallies for liuyao cases only
ly = [b for _, b in B21 + B22 if "六爻" in b["prediction_text"] or "liuyao" in b["basis"]]
cm = sum(1 for b in ly if b["trigger"]["changed_main"])
ru = sum(1 for b in ly if b["trigger"]["reserve_used"])
di = sum(1 for b in ly if b["trigger"]["disputed"])
print("liuyao cases:", len(ly), "changed_main:", cm, "reserve_used:", ru, "disputed:", di)
print("total written:", len(B21) + len(B22))
